package com.shatteredpixel.shatteredpixeldungeon.halo;

import java.util.Arrays;
import java.util.List;

/**
 * HALO Archetypes scaffold, per Labyrinth design (Seeker/Trickster/Sage/Champion/Shadow).
 * (Names map to Seeker, Thui, Keni, Tir, Shanau.)  fileciteturn0file0
 */
public enum Archetype {
    SEEKER("Seeker", "Balanced beginner"),
    TRICKSTER("Thui", "High agility, stealth tools"),
    SAGE("Keni", "Runes & identification"),
    CHAMPION("Tir", "Defense & melee"),
    SHADOW("Shanau", "High risk / high reward");

    public final String codename;
    public final String blurb;
    Archetype(String codename, String blurb){ this.codename = codename; this.blurb = blurb; }

    public static List<Archetype> core(){ return Arrays.asList(SEEKER, TRICKSTER, SAGE, CHAMPION, SHADOW); }

    public static Archetype fromString(String s){
        if (s == null) return SEEKER;
        for (Archetype a : values()){
            if (a.name().equalsIgnoreCase(s) || a.codename.equalsIgnoreCase(s)) return a;
        }
        return SEEKER;
    }
}
```

