package com.shatteredpixel.shatteredpixeldungeon.halo;

import com.shatteredpixel.shatteredpixeldungeon.SPDSettings;
import com.watabou.utils.Bundle;

/**
 * Persistent meta-progression: Memory Echoes (soft-capped).
 * Earn echoes from achievements (here: boss kills); cap prevents runaway power creep.  fileciteturn0file0
 */
public class MemoryEchoes {

    // Rolling cap per design (“last N echoes active”), we model as a soft integer cap for v1.  fileciteturn0file0
    public static final int SOFT_CAP = 50;

    public static int get(){ return SPDSettings.memoryEchoes(); }

    public static void award(int amount){
        int curr = SPDSettings.memoryEchoes();
        int next = curr + Math.max(0, amount);
        SPDSettings.memoryEchoes(Math.min(next, SOFT_CAP));
    }

    public static void spend(int amount){
        int curr = SPDSettings.memoryEchoes();
        SPDSettings.memoryEchoes(Math.max(0, curr - Math.max(0, amount)));
    }

    public static void reset(){ SPDSettings.memoryEchoes(0); }

    public static void store(Bundle b){ b.put("halo_memory_echoes", get()); }
    public static void restore(Bundle b){ if (b.contains("halo_memory_echoes")) SPDSettings.memoryEchoes(b.getInt("halo_memory_echoes")); }
}
```

